function numIslands(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  // Work on a copy so we don't mutate the caller's grid.
  const g = grid.map((row) => [...row]);

  function floodFill(r, c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols || g[r][c] !== '1') return;
    g[r][c] = '0'; // mark visited
    floodFill(r + 1, c);
    floodFill(r - 1, c);
    floodFill(r, c + 1);
    floodFill(r, c - 1);
  }

  let islands = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (g[r][c] === '1') {
        islands++;
        floodFill(r, c);
      }
    }
  }

  return islands;
}

class Node {
  constructor(val, neighbors) {
    this.val = val === undefined ? 0 : val;
    this.neighbors = neighbors === undefined ? [] : neighbors;
  }
}

// Builds real Node objects from a LeetCode-style adjacency list
// (adjList[i] holds the neighbor VALUES, 1-indexed, of node i + 1).
// Returns the entry node (node 1), or null for an empty graph.
function buildGraph(adjList) {
  if (!adjList || adjList.length === 0) return null;
  const nodes = adjList.map((_, i) => new Node(i + 1));
  adjList.forEach((neighborVals, i) => {
    nodes[i].neighbors = neighborVals.map((v) => nodes[v - 1]);
  });
  return nodes[0];
}

function cloneGraph(node) {
  if (!node) return null;

  const visited = new Map(); // original Node -> cloned Node

  function dfs(original) {
    if (visited.has(original)) return visited.get(original);

    const clone = new Node(original.val);
    visited.set(original, clone);

    for (const neighbor of original.neighbors) {
      clone.neighbors.push(dfs(neighbor));
    }

    return clone;
  }

  return dfs(node);
}

// --- Judge wrapper: builds the graph, clones it, and serializes the CLONE
// back to an adjacency-list array so it can be compared to `expected`.
// It also fails loudly (throws) if the clone reuses any original Node
// reference, proving the copy is genuinely new objects, not aliases.
function cloneGraphJudge(adjList) {
  const original = buildGraph(adjList);
  if (!original) return [];

  const clone = cloneGraph(original);

  const originalNodes = new Set();
  (function collectOriginal(n, seen) {
    if (seen.has(n)) return;
    seen.add(n);
    originalNodes.add(n);
    n.neighbors.forEach((nb) => collectOriginal(nb, seen));
  })(original, new Set());

  const order = [];
  (function collectClone(n, seen) {
    if (seen.has(n)) return;
    seen.add(n);
    if (originalNodes.has(n)) {
      throw new Error('Clone reused an original node reference instead of creating a new one.');
    }
    order.push(n);
    n.neighbors.forEach((nb) => collectClone(nb, seen));
  })(clone, new Set());

  order.sort((a, b) => a.val - b.val);
  const indexOf = new Map();
  order.forEach((n, i) => indexOf.set(n, i + 1));

  const serialized = [];
  order.forEach((n) => {
    serialized[indexOf.get(n) - 1] = n.neighbors
      .map((nb) => indexOf.get(nb))
      .sort((a, b) => a - b);
  });

  return serialized;
}

